python
def paidReservationsTotalReceipt(drawers):
    a=drawers
    out=[]
    rows=sorted(a,key=lambda r:(r[1],r[0],r[2]))
    dp=[0]
    for i,(start,end,reward) in enumerate(rows):
        left,right=0,i
        while left<right:
            mid=(left+right)//2
            if rows[mid][1]<=start: left=mid+1
            else: right=mid
        dp.append(max(dp[i],dp[left]+reward))
    out=dp[1:]
    return sum(out)


